"""Zoo 1.134.0: a light row's `bake_reach` (Deli Counter >= 0.279.0) rides every lamp of its row and its marker as
`lux_bake_reach`, for Lux >= 0.80.0's bake (the walker: "far too dark in teh super market"; the factory's
docs/findings/black_gondola_ends/).

What it changes (anchored; each file pinned by hash; nothing written on a miss):
  * zoo_keeper/core/fixtures.py, zoo_keeper/bpylayer/build.py, tests/test_fixtures.py -- edited.
  * VERSION 1.133.0 -> 1.134.0, CHANGELOG.

Generated by `patches/zoo_bake_reach/gen_zoo_bake_reach.py` from a proven clone.

    python patches/patch_zoo_bake_reach.py
"""
import hashlib
import pathlib
import sys

ROOT = pathlib.Path(__file__).resolve().parents[1]
REPO = ROOT / "zoo"
PINS = {'zoo_keeper/core/fixtures.py': 'f360fff265cecd04', 'zoo_keeper/bpylayer/build.py': '23e782c597d6150d', 'tests/test_fixtures.py': '63e34c4cea6cc7d2'}
EDITS = {'zoo_keeper/core/fixtures.py': [('lines 316-317', '                "reach": float(a.get("reach", 0.0) or 0.0),\n                "seed_offset": _seed_offset(aid, j),\n', '                "reach": float(a.get("reach", 0.0) or 0.0),\n                # 1.134.0: a row Deli Counter (>= 0.279.0) asks to bake\n                # further than it lights live carries `bake_reach`, the\n                # horizontal metres its lightmap must reach; Lux >= 0.80.0\n                # lends the lamp that range only while a lightmap bakes. 0.0\n                # everywhere else, and then no marker carries it.\n                "bake_reach": float(a.get("bake_reach", 0.0) or 0.0),\n                "seed_offset": _seed_offset(aid, j),\n')], 'zoo_keeper/bpylayer/build.py': [('lines 884-885', '            mk["lux_reach"] = float(p["reach"])\n        coll.objects.link(mk)\n', '            mk["lux_reach"] = float(p["reach"])\n        # 1.134.0: the same, for the reach a row\'s lightmap bakes to\n        if float(p.get("bake_reach", 0.0)) > 0.0:\n            mk["lux_bake_reach"] = float(p["bake_reach"])\n        coll.objects.link(mk)\n')], 'tests/test_fixtures.py': [('lines 253-254', "\n# --- the club set's hardware (v0.94) ------------------------------------------\n", '\ndef test_bake_reach_rides_every_lamp_of_its_row_and_no_other():\n    # 1.134.0: Deli Counter stamps `bake_reach` on a supermarket\'s rows\n    p = fixtures.plan(_manifest([\n        {"id": "sales_floor_ceiling", "type": "fluorescent", "pos": [0, 0, 4.1],\n         "row": {"count": 3, "spacing": 5.5}, "drop": 4.1, "bake_reach": 5.5},\n        {"id": "stockroom_ceiling", "type": "fluorescent", "pos": [0, 9, 3.8],\n         "row": {"count": 2, "spacing": 4.0}, "drop": 3.8, "reach": 6.0}]))\n    got = {}\n    for pl in p["placements"]:\n        got.setdefault(pl["anchor_id"], []).append((pl["bake_reach"], pl["reach"]))\n    assert got == {"sales_floor_ceiling": [(5.5, 0.0)] * 3,\n                   "stockroom_ceiling": [(0.0, 6.0)] * 2}\n\n\n# --- the club set\'s hardware (v0.94) ------------------------------------------\n'), ('lines 438-439', '\ndef test_bpy_the_club_gets_hardware_and_no_marker_with_it(tmp_path):\n', '\ndef test_bpy_a_row_marks_its_bake_reach_and_no_other_row_does(tmp_path):\n    # 1.134.0: as the reach, for Lux\'s bake -- absent on the control\n    pytest.importorskip("bpy")\n    import json\n    import os\n    from zoo_keeper.bpylayer import build\n    manifest = {"light_manifest_version": "1.2.0", "building_id": "bake_reach_bpy",\n                "space": "Blender Z-up, meters", "anchors": [\n                    {"id": "sales_floor_ceiling", "type": "fluorescent", "pos": [0.0, 0.0, 4.1],\n                     "rot_y": 0.0, "row": {"count": 2, "spacing": 5.5}, "drop": 4.1, "bake_reach": 5.5},\n                    {"id": "stockroom_ceiling", "type": "fluorescent", "pos": [0.0, 9.0, 3.8],\n                     "rot_y": 0.0, "row": {"count": 1, "spacing": 0.0}, "drop": 3.8}]}\n    build.build_fixtures(manifest, str(tmp_path), theme="delco", options={"save_blend": False})\n    with open(os.path.join(str(tmp_path), "bake_reach_bpy_fixtures.built.json"), encoding="utf-8") as fh:\n        index = json.load(fh)\n    j = _gltf(os.path.join(str(tmp_path), index["files"]["glb"]))\n    marks = [n.get("extras", {}) for n in j["nodes"] if n["name"].startswith("LuxEmit")]\n    got = sorted((m["lux_anchor_id"], m.get("lux_bake_reach")) for m in marks)\n    assert got == [("sales_floor_ceiling", 5.5), ("sales_floor_ceiling", 5.5),\n                   ("stockroom_ceiling", None)], got\n\n\ndef test_bpy_the_club_gets_hardware_and_no_marker_with_it(tmp_path):\n')]}
NEW_FILES = {}
CHANGELOG = '## [1.134.0] - a light row\'s `bake_reach` rides its lamps\' markers\n\nThe walker: "far too dark in teh super market". Measured in the factory\'s docs/findings/black_gondola_ends/: the\nsupermarket\'s baked lamps light their store when the lightmap bakes them further than their live range. Lux 0.80.0\nlends a static lamp that range only while a lightmap bakes. Deli Counter 0.279.0 asks for it on a supermarket\'s rows\nas `bake_reach`, the horizontal metres the bake must reach, which is the row\'s lamp spacing.\n\n### Added\n- **`fixtures.plan`**: every lamp of a row carries the row\'s `bake_reach`, 0.0 where it has none, beside `reach`.\n- **`build.build_fixtures`**: a lamp\'s marker carries `lux_bake_reach`, where Lux\'s spawner reads it, only when its\n  row has one. Every other building\'s markers, and GLB, stay as they were (as `lux_reach`, 1.21.0).\n\n### Tests\n- `tests/test_fixtures.py`:\n  - `bake_reach` rides every lamp of its row and no other\'s, a storefront row\'s `reach` beside it untouched;\n  - built in Blender, the GLB\'s markers carry `lux_bake_reach` on that row\'s lamps and not on the control row\'s.\n\n  The first fails on 1.133.0. The fixture tests pass 39 of 39 in Blender 5.1.1.\n\n'
OLD_VERSION, NEW_VERSION = '1.133.0', '1.134.0'


def _sha(b):
    return hashlib.sha256(b).hexdigest()[:16]


def _read(name):
    """The file's LF text and whether it is CRLF on disk; refuses mixed endings and a file that is not the pinned one."""
    raw = (REPO / name).read_bytes()
    crlf, lf = raw.count(b"\r\n"), raw.count(b"\n")
    if crlf not in (0, lf):
        raise SystemExit("REFUSED: zoo/%s has mixed line endings (%d CRLF of %d); nothing written"
                         % (name, crlf, lf))
    text = raw.decode("utf-8").replace("\r\n", "\n")
    if _sha(text.encode("utf-8")) != PINS[name]:
        raise SystemExit("REFUSED: zoo/%s is %s, not the %s this patch was written against; nothing "
                         "written" % (name, _sha(text.encode("utf-8")), PINS[name]))
    return text, crlf > 0


def main(argv):
    # every file worked out and checked before any is written
    out = {}
    for name, edits in EDITS.items():
        text, crlf = _read(name)
        for what, old, new in edits:
            if text.count(old) != 1:
                raise SystemExit("REFUSED: zoo/%s: the anchor at %s is there %d times; nothing written"
                                 % (name, what, text.count(old)))
            text = text.replace(old, new)
        out[name] = text.replace("\n", "\r\n") if crlf else text
    for name in NEW_FILES:
        if (REPO / name).exists():
            raise SystemExit("REFUSED: zoo/%s exists already; nothing written" % name)
    v = REPO / "VERSION"
    if v.read_bytes().decode("utf-8") != OLD_VERSION:
        raise SystemExit("REFUSED: VERSION reads %r, not %s; nothing written" % (v.read_text(), OLD_VERSION))
    cl = REPO / "CHANGELOG.md"
    craw = cl.read_bytes()
    if b"\r\n" in craw or not craw.startswith(b"## [" + OLD_VERSION.encode() + b"]"):
        raise SystemExit("REFUSED: CHANGELOG.md is not LF opening on %s; nothing written" % OLD_VERSION)
    for name, text in out.items():
        (REPO / name).write_bytes(text.encode("utf-8"))
    for name, text in NEW_FILES.items():
        (REPO / name).write_bytes(text.encode("utf-8"))
    v.write_bytes(NEW_VERSION.encode("utf-8"))
    cl.write_bytes(CHANGELOG.encode("utf-8") + craw)
    print("Zoo %s applied: %d files edited, %d written, VERSION, CHANGELOG. Now, in zoo/: the "
          "suite" % (NEW_VERSION, len(out), len(NEW_FILES)))
    return 0


if __name__ == "__main__":
    sys.exit(main(sys.argv[1:]))
